effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
bool u_xlatb3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
vec2 u_xlat12;
float u_xlat18;
float u_xlat19;
float u_xlat20;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12.x = (-_direction) + 180.0;
    u_xlat12.x = u_xlat12.x * 0.0174532942;
    u_xlat1.x = sin(u_xlat12.x);
    u_xlat2.x = cos(u_xlat12.x);
    u_xlat3.x = sin((-u_xlat12.x));
    u_xlat3.y = u_xlat2.x;
    u_xlat2.x = dot(u_xlat3.yx, u_xlat0.xy);
    u_xlat3.z = u_xlat1.x;
    u_xlat2.y = dot(u_xlat3.zy, u_xlat0.xy);
    u_xlat0.xy = u_xlat2.xy * vec2(_scale.x, _scale.y) + vec2(0.5, 0.5);
    u_xlat0.xy = (int(_type) != 0) ? acScreenNorm.xy : u_xlat0.xy;
    u_xlat1.xyz = _color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat1.xyz = _color.xyz * u_xlat1.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat1.xyz = u_xlat1.xyz * _color.xyz;
    u_xlat12.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = u_xlat12.xy * vec2(_scale.x, _scale.y) + vec2(0.5, 0.5);
    u_xlat12.xy = u_xlat12.xy + (-_offset.xy);
    u_xlat2 = texture(texture0, u_xlat12.xy);
    u_xlat12.xy = texture(texture1, u_xlat12.xy).xy;
    u_xlat12.xy = u_xlat12.xy * vec2(2.0, 2.0) + vec2(-1.0, -1.0);
    u_xlat19 = (-u_xlat2.w) * _transparency + 1.0;
    if(int(_type) == 0) {
        u_xlat20 = texture(texture2, u_xlat0.xy).x;
    } else {
        u_xlatb3 = int(_type)==1;
        if(u_xlatb3){
            u_xlat20 = texture(texture3, u_xlat0.xy).x;
        } else {
            u_xlatb3 = int(_type)==2;
            if(u_xlatb3){
                u_xlat20 = texture(texture4, u_xlat0.xy).x;
            } else {
                u_xlat20 = texture(texture5, u_xlat0.xy).x;
            }
        }
    }
    u_xlat0.x = u_xlat19 * _spread;
    u_xlat0.x = u_xlat0.x * -2.0 + 1.0;
    u_xlat0.x = (-u_xlat0.x) + u_xlat20;
    u_xlat0.x = u_xlat0.x / _smoothness;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat6.xy = u_xlat12.xy * vec2(_refraction);
    u_xlat6.xy = u_xlat6.xy * u_xlat0.xx + acScreenNorm.xy;
    u_xlat6.xyz = texture(inputImg, u_xlat6.xy).xyz;
    u_xlat3.xyz = (-u_xlat6.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat4.xyz = (-u_xlat2.xyz) * u_xlat1.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat3.xyz = (-u_xlat3.xyz) * u_xlat4.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat2.xyz * u_xlat1.xyz + (-u_xlat3.xyz);
    u_xlat1.xyz = _color.www * u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1.xyz = (-u_xlat6.xyz) + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat0.xxx * u_xlat1.xyz + u_xlat6.xyz;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat0.w = u_xlat1.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat1 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat18 = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat18 : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        fragColor.xyz = u_xlat0.xyz;
        fragColor.w = u_xlat1.w;
    }
    return;
}
